// Run after `pnpm run openapi:generate:check` (official tool output only).
// Never edit src/api/generated by hand to satisfy this gate.
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import test from 'node:test'

const frontend = join(dirname(fileURLToPath(import.meta.url)), '..')
const types = readFileSync(join(frontend, 'src/api/generated/types.gen.ts'), 'utf8')
const sdk = readFileSync(join(frontend, 'src/api/generated/sdk.gen.ts'), 'utf8')
const marker = '// This file is auto-generated by @hey-api/openapi-ts'
const operations = [
  'listSuppliers', 'createSupplier', 'getSupplier', 'updateSupplier',
  'getSupplierCompanyUsages', 'replaceSupplierCompanyUsages', 'setSupplierState',
]
function typeBody(name) {
  const match = types.match(new RegExp(`export type ${name} = \\{([\\s\\S]*?)^\\};`, 'm'))
  assert.ok(match, `Missing generated ${name} DTO; regenerate SDK first`)
  return match[1]
}

test('Supplier generated artifacts have tool-owned header', () => {
  assert.ok(types.startsWith(marker))
  assert.ok(sdk.startsWith(marker))
})
test('all seven Supplier SDK exports are generated exactly once', () => {
  for (const operation of operations) {
    const found = sdk.match(new RegExp(`export const ${operation}\\b`, 'g')) ?? []
    assert.equal(found.length, 1, `${operation} SDK export`)
  }
})
test('canonical Supplier DTOs are generated', () => {
  for (const dto of [
    'Supplier', 'SupplierCreate', 'SupplierPatch', 'SupplierCompanyUsage',
    'SupplierCompanyUsagePut', 'SupplierSetState',
  ]) typeBody(dto)
  assert.match(types, /export type SupplierExpectedVersion\s*=/)
  assert.match(types, /export type SupplierRowVersion\s*=/)
})
test('read Supplier has version, Company Usage, advisory state targets and row hints', () => {
  const source = typeBody('Supplier')
  for (const key of ['row_version', 'supplier_type', 'supplier_group_code', 'all_companies']) {
    assert.match(source, new RegExp(`\\b${key}:`))
  }
  assert.match(source, /company_ids\?:/)
  assert.match(source, /allowed_actions\?:\s*\{/)
  assert.match(source, /edit\?: boolean/)
  assert.match(source, /setstate\?: boolean/)
  assert.match(source, /setstate_targets\?:/)
  assert.doesNotMatch(source, /\b(bank_account|bank_ciphertext|bank_key|bank_iban|bank_number)\b/i)
})
test('mutations require CAS and cannot transfer owner, State, Bank or Company Usage through PATCH', () => {
  for (const dto of ['SupplierPatch', 'SupplierCompanyUsagePut', 'SupplierSetState']) {
    assert.match(typeBody(dto), /expected_version:\s*SupplierExpectedVersion;/)
  }
  const patch = typeBody('SupplierPatch')
  for (const key of ['status','supplier_code','company_ids','all_companies','bank_account','bank_number']) {
    assert.doesNotMatch(patch, new RegExp(`\\b${key}\\??:`), `${key} forbidden on PATCH`)
  }
  assert.match(typeBody('SupplierSetState'), /status:/)
})
test('Supplier List query is flat and page_size capped by canonical contract', () => {
  const block = typeBody('ListSuppliersData')
  for (const key of ['status','supplier_type','supplier_group_code','company_id','page_size']) {
    assert.match(block, new RegExp(`\\b${key}\\?:`))
  }
  assert.doesNotMatch(block, /filter\?:\s*\{/)
})
